class Solution {
    public int[] corpFlightBookings(int[][] bookings, int n) {
        int[] diff = new int[n + 1];                // diff[i] = ans[i] - ans[i-1]
        for (int[] b : bookings) {
            diff[b[0] - 1] += b[2];                 // 从 first 开始多了 seats
            diff[b[1]] -= b[2];                     // 过了 last 又少了 seats
        }
        int[] ans = new int[n];
        int cur = 0;
        for (int i = 0; i < n; i++) {
            cur += diff[i];                         // 前缀和还原出每个位置的值
            ans[i] = cur;
        }
        return ans;
    }
}

